using DriveOS.Modules.TrainingDelivery.Domain.Incidents; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.TrainingDelivery.Infrastructure.Persistence.Configurations;
internal sealed class TrainingIncidentHistoryConfiguration : IEntityTypeConfiguration<TrainingIncidentHistoryEntry>{public void Configure(EntityTypeBuilder<TrainingIncidentHistoryEntry>b){b.ToTable("training_incident_history");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new TrainingIncidentHistoryEntryId(x));b.Property(x=>x.TrainingIncidentId).HasConversion(x=>x.Value,x=>new TrainingIncidentId(x)).IsRequired();b.Property(x=>x.ActorUserId).HasConversion(x=>x.Value,x=>new UserId(x)).IsRequired();b.Property(x=>x.RequestFingerprint).HasMaxLength(64).IsRequired();b.Property(x=>x.Reason).HasMaxLength(4000);b.HasIndex(x=>new{x.TrainingIncidentId,x.OperationId}).IsUnique();b.HasIndex(x=>new{x.TrainingIncidentId,x.OccurredAtUtc});}}
